public void testIE5MacBug() throws FileUploadException {
    final var fileItems = parseUpload(upload, // @formatter:off
    "-----1234\r\n" + "Content-Disposition: form-data; name=\"field1\"\r\n" + "\r\n" + "fieldValue\r\n" + // NOTE \r missing
