/**
 * Test for multipart/related without any content-disposition Header.
 * This kind of Content-Type is commonly used by SOAP-Requests with Attachments (MTOM)
 */
@Test
public void testMultipleRelated() throws Exception {
    final String soapEnvelope = "<soap:Envelope xmlns:soap=\"http://www.w3.org/2003/05/soap-envelope\">\r\n" + "  <soap:Header></soap:Header>\r\n" + "  <soap:Body>\r\n" + "    <ns1:Test xmlns:ns1=\"http://www.test.org/some-test-namespace\">\r\n" + "      <ns1:Attachment>\r\n" + "        <xop:Include xmlns:xop=\"http://www.w3.org/2004/08/xop/include\"" + " href=\"ref-to-attachment%40some.domain.org\"/>\r\n" + "      </ns1:Attachment>\r\n" + "    </ns1:Test>\r\n" + "  </soap:Body>\r\n" + "</soap:Envelope>";
    final String text = "-----1234\r\n" + "content-type: application/xop+xml; type=\"application/soap+xml\"\r\n" + "\r\n" + soapEnvelope + "\r\n" + "-----1234\r\n" + "Content-type: text/plain\r\n" + "content-id: <ref-to-attachment@some.domain.org>\r\n" + "\r\n" + "some text/plain content\r\n" + "-----1234--\r\n";
    final var bytes = text.getBytes(StandardCharsets.US_ASCII);
    final var fileItems = parseUpload(upload, bytes, "multipart/related; boundary=---1234;" + " type=\"application/xop+xml\"; start-info=\"application/soap+xml\"");
    assertEquals(2, fileItems.size());
    final var part1 = fileItems.get(0);
    assertNull(part1.getFieldName());
    assertFalse(part1.isFormField());
    assertEquals(soapEnvelope, part1.getString());
    final var part2 = fileItems.get(1);
    assertNull(part2.getFieldName());
    assertFalse(part2.isFormField());
    assertEquals("some text/plain content", part2.getString());
    assertEquals("text/plain", part2.getContentType());
    assertNull(part2.getName());
}

/**
 * Parse a very long file upload by using a progress listener.
 *
 * @throws IOException Test failure.
 */
@Test
public void testProgressListener() throws IOException {
    final var numItems = 512;
    final var baos = new ByteArrayOutputStream();
    for (var i = 0; i < numItems; i++) {
        final var header = "-----1234\r\n" + "Content-Disposition: form-data; name=\"field" + (i + 1) + "\"\r\n" + "\r\n";
        baos.write(header.getBytes(StandardCharsets.US_ASCII));
        for (var j = 0; j < 16384 + i; j++) {
            baos.write((byte) j);
        }
        baos.write("\r\n".getBytes(StandardCharsets.US_ASCII));
    }
    baos.write("-----1234--\r\n".getBytes(StandardCharsets.US_ASCII));
    final var requestBytes = baos.toByteArray();
    var request = newMockHttpServletRequest(requestBytes, null, Constants.CONTENT_TYPE, null);
    runTest(numItems, requestBytes.length, request);
    request = newMockHttpServletRequest(requestBytes, -1L, Constants.CONTENT_TYPE, null);
    runTest(numItems, requestBytes.length, request);
}

/**
 * Checks, whether limiting the file size works.
 *
 * @throws IOException Test failure.
 */
@Test
public void testFileSizeLimit() throws IOException {
    final var content = "This is the content of the file\n";
    final var contentSize = content.getBytes().length;
    // @formatter:off
    final var request = "-----1234\r\n" + "Content-Disposition: form-data; name=\"file\"; filename=\"foo.tab\"\r\n" + "Content-Type: text/whatever\r\n" + "\r\n" + content + "\r\n" + "-----1234--\r\n";
    // @formatter:on
    var upload = newFileUpload();
    upload.setFileSizeMax(-1);
    var req = newMockHttpServletRequest(request, null, null);
    var fileItems = upload.parseRequest(req);
    assertEquals(1, fileItems.size());
    var item = fileItems.get(0);
    assertEquals(content, new String(item.get()));
    upload = newFileUpload();
    upload.setFileSizeMax(40);
    req = newMockHttpServletRequest(request, null, null);
    fileItems = upload.parseRequest(req);
    assertEquals(1, fileItems.size());
    item = fileItems.get(0);
    assertEquals(content, new String(item.get()));
    upload = newFileUpload();
    upload.setFileSizeMax(contentSize);
    req = newMockHttpServletRequest(request, null, null);
    fileItems = upload.parseRequest(req);
    assertEquals(1, fileItems.size());
    item = fileItems.get(0);
    assertEquals(content, new String(item.get()));
    upload = newFileUpload();
    upload.setFileSizeMax(contentSize - 1);
    req = newMockHttpServletRequest(request, null, null);
    try {
        upload.parseRequest(req);
        fail("Expected exception.");
    } catch (final FileUploadByteCountLimitException e) {
        assertEquals(contentSize - 1, e.getPermitted());
    }
    upload = newFileUpload();
    upload.setFileSizeMax(30);
    req = newMockHttpServletRequest(request, null, null);
    try {
        upload.parseRequest(req);
        fail("Expected exception.");
    } catch (final FileUploadByteCountLimitException e) {
        assertEquals(30, e.getPermitted());
    }
}

/**
 * Checks, whether a faked Content-Length header is detected.
 *
 * @throws IOException Test failure.
 */
@Test
public void testFileSizeLimitWithFakedContentLength() throws IOException {
    // @formatter:off
    final var request = "-----1234\r\n" + "Content-Disposition: form-data; name=\"file\"; filename=\"foo.tab\"\r\n" + "Content-Type: text/whatever\r\n" + "Content-Length: 10\r\n" + "\r\n" + "This is the content of the file\n" + "\r\n" + "-----1234--\r\n";
    // @formatter:on
    var upload = newFileUpload();
    upload.setFileSizeMax(-1);
    var req = newMockHttpServletRequest(request, null, null);
    var fileItems = upload.parseRequest(req);
    assertEquals(1, fileItems.size());
    var item = fileItems.get(0);
    assertEquals("This is the content of the file\n", new String(item.get()));
    upload = newFileUpload();
    upload.setFileSizeMax(40);
    req = newMockHttpServletRequest(request, null, null);
    fileItems = upload.parseRequest(req);
    assertEquals(1, fileItems.size());
    item = fileItems.get(0);
    assertEquals("This is the content of the file\n", new String(item.get()));
    // provided Content-Length is larger than the FileSizeMax -> handled by ctor
    upload = newFileUpload();
    upload.setFileSizeMax(5);
    req = newMockHttpServletRequest(request, null, null);
    try {
        upload.parseRequest(req);
        fail("Expected exception.");
    } catch (final FileUploadByteCountLimitException e) {
        assertEquals(5, e.getPermitted());
    }
    // provided Content-Length is wrong, actual content is larger -> handled by LimitedInputStream
    upload = newFileUpload();
    upload.setFileSizeMax(15);
    req = newMockHttpServletRequest(request, null, null);
    try {
        upload.parseRequest(req);
        fail("Expected exception.");
    } catch (final FileUploadByteCountLimitException e) {
        assertEquals(15, e.getPermitted());
    }
}

